[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)]
    [string]$Root
)

$ErrorActionPreference = 'Stop'

function Read-JsonFile([string]$Path, [string]$Label) {
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { throw "$Label does not exist: $Path" }
    try { return (Get-Content -Raw -LiteralPath $Path | ConvertFrom-Json) }
    catch { throw "$Label is not valid JSON: $($_.Exception.Message)" }
}

function Get-PropertyValue([object]$Object, [string]$Name) {
    if ($null -eq $Object) { throw "Missing object containing '$Name'" }
    $property = $Object.PSObject.Properties[$Name]
    if ($null -eq $property) { throw "Missing required managed setting '$Name'" }
    return $property.Value
}

function Test-ExactAllowed([object]$Value, [object[]]$Allowed) {
    foreach ($candidate in $Allowed) {
        if ($Value -is [string] -and $candidate -is [string]) {
            if ($Value -ceq $candidate) { return $true }
        }
        elseif ($Value -eq $candidate) { return $true }
    }
    return $false
}

function Assert-ContractValue([object]$Value, [object]$Entry) {
    $validType = switch ([string]$Entry.Type) {
        'string'  { $Value -is [string] }
        'boolean' { $Value -is [bool] }
        'integer' { $Value -is [int] -or $Value -is [long] }
        'number'  { $Value -is [int] -or $Value -is [long] -or $Value -is [double] -or $Value -is [decimal] }
        default   { $false }
    }
    if (-not $validType) { throw "$($Entry.Group).$($Entry.Key) must be $($Entry.Type)" }

    $allowedProperty = $Entry.PSObject.Properties['Allowed']
    if ($null -ne $allowedProperty -and -not (Test-ExactAllowed $Value @($allowedProperty.Value))) {
        throw "$($Entry.Group).$($Entry.Key) has unsupported value '$Value'"
    }
    $maxLengthProperty = $Entry.PSObject.Properties['MaxLength']
    if ($null -ne $maxLengthProperty -and ([string]$Value).Length -gt [int]$maxLengthProperty.Value) {
        throw "$($Entry.Group).$($Entry.Key) exceeds $($maxLengthProperty.Value) characters"
    }
}

function Set-JsonPath([object]$Object, [string]$DotPath, [object]$Value) {
    $segments = @($DotPath -split '\.')
    $cursor = $Object
    for ($index = 0; $index -lt $segments.Count - 1; $index++) {
        $segment = $segments[$index]
        $property = $cursor.PSObject.Properties[$segment]
        if ($null -eq $property -or $null -eq $property.Value) {
            $child = [pscustomobject]@{}
            if ($null -eq $property) { $cursor | Add-Member -NotePropertyName $segment -NotePropertyValue $child }
            else { $property.Value = $child }
            $cursor = $child
        }
        else { $cursor = $property.Value }
    }
    $leaf = $segments[-1]
    $leafProperty = $cursor.PSObject.Properties[$leaf]
    if ($null -eq $leafProperty) { $cursor | Add-Member -NotePropertyName $leaf -NotePropertyValue $Value }
    else { $leafProperty.Value = $Value }
}

function Resolve-EffectiveSavePath([string]$RootPath, [string]$ConfiguredPath) {
    if ([string]::IsNullOrWhiteSpace($ConfiguredPath)) { throw 'WorldConfig.SaveFileLocation is blank' }
    if ([IO.Path]::IsPathRooted($ConfiguredPath)) { return [IO.Path]::GetFullPath($ConfiguredPath) }
    $serverRoot = [IO.Path]::GetFullPath((Join-Path $RootPath 'server'))
    $resolved = [IO.Path]::GetFullPath((Join-Path $serverRoot $ConfiguredPath))
    $dataRoot = [IO.Path]::GetFullPath((Join-Path $RootPath 'data')).TrimEnd('\','/') + [IO.Path]::DirectorySeparatorChar
    if (-not $resolved.StartsWith($dataRoot, [StringComparison]::OrdinalIgnoreCase)) {
        throw "Relative SaveFileLocation escapes the instance data directory: $ConfiguredPath"
    }
    return $resolved
}

function ConvertTo-CommandValue([object]$Value) {
    if ($Value -is [bool]) { return $Value.ToString().ToLowerInvariant() }
    if ($Value -is [IFormattable]) { return $Value.ToString($null, [Globalization.CultureInfo]::InvariantCulture) }
    return [string]$Value
}

function ConvertTo-StableJson([object]$Value) {
    return (($Value | ConvertTo-Json -Depth 40) + "`n")
}

function Write-ValidatedTemp([string]$Destination, [string]$Text) {
    $directory = Split-Path -Parent $Destination
    $temporary = Join-Path $directory ('.' + [IO.Path]::GetFileName($Destination) + '.tmp-' + [guid]::NewGuid().ToString('N'))
    [IO.File]::WriteAllText($temporary, $Text, (New-Object Text.UTF8Encoding $false))
    try { Get-Content -Raw -LiteralPath $temporary | ConvertFrom-Json | Out-Null }
    catch { Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue; throw "Rendered JSON validation failed for $Destination" }
    return $temporary
}

function Replace-File([string]$Temporary, [string]$Destination, [string]$Backup = '') {
    if (Test-Path -LiteralPath $Destination -PathType Leaf) {
        if ([string]::IsNullOrEmpty($Backup)) {
            $discardBackup = Join-Path ([IO.Path]::GetDirectoryName($Destination)) ('.amp-world-discard-' + [guid]::NewGuid().ToString('N'))
            try { [IO.File]::Replace($Temporary, $Destination, $discardBackup, $true) }
            finally { Remove-Item -LiteralPath $discardBackup -Force -ErrorAction SilentlyContinue }
        }
        else {
            [IO.File]::Replace($Temporary, $Destination, $Backup, $true)
        }
    }
    else { [IO.File]::Move($Temporary, $Destination) }
}

function Read-ManagedState([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        return [pscustomobject]@{ Valid=$false; Commands=@(); Reason='missing' }
    }
    try {
        $value = Get-Content -Raw -LiteralPath $Path | ConvertFrom-Json
        if ($value.SchemaVersion -ne 1 -or $null -eq $value.PSObject.Properties['ManagedCommands']) { throw 'unsupported state shape' }
        $commands = @($value.ManagedCommands)
        foreach ($command in $commands) { if (-not ($command -is [string])) { throw 'ManagedCommands must contain strings' } }
        return [pscustomobject]@{ Valid=$true; Commands=$commands; Reason='' }
    }
    catch { return [pscustomobject]@{ Valid=$false; Commands=@(); Reason='invalid' } }
}

$rootPath = [IO.Path]::GetFullPath($Root)
$dataPath = Join-Path $rootPath 'data'
$managedPath = Join-Path $dataPath 'amp-world-settings.json'
$contractPath = Join-Path $dataPath 'amp-world-settings-contract.json'
$serverConfigPath = Join-Path $dataPath 'serverconfig.json'
$statePath = Join-Path $dataPath 'amp-world-settings-state.json'
$backupPath = Join-Path $dataPath 'serverconfig.json.amp-world-backup'

try {
    $managed = Read-JsonFile $managedPath 'AMP world settings'
    $contract = Read-JsonFile $contractPath 'AMP world settings contract'
    $serverConfig = Read-JsonFile $serverConfigPath 'Vintage Story serverconfig'
    if ($managed.SchemaVersion -ne 1) { throw "Unsupported AMP world settings schema version '$($managed.SchemaVersion)'" }
    if (-not ($managed.ApplyToExistingWorld -is [bool])) { throw 'ApplyToExistingWorld must be boolean' }
    if ($contract.Count -ne 68) { throw "World settings contract must contain 68 entries, found $($contract.Count)" }

    $values = [ordered]@{}
    foreach ($entry in $contract) {
        $group = Get-PropertyValue $managed ([string]$entry.Group)
        $value = Get-PropertyValue $group ([string]$entry.Key)
        Assert-ContractValue $value $entry
        $values["$($entry.Group).$($entry.Key)"] = $value
    }

    $worldConfig = Get-PropertyValue $serverConfig 'WorldConfig'
    $saveLocation = [string](Get-PropertyValue $worldConfig 'SaveFileLocation')
    $savePath = Resolve-EffectiveSavePath $rootPath $saveLocation
    $existing = Test-Path -LiteralPath $savePath -PathType Leaf
    $managedCommands = @()
    $stateOutput = $null

    foreach ($entry in $contract | Where-Object { $_.Group -eq 'Server' }) {
        Set-JsonPath $serverConfig ([string]$entry.CreationPath) $values["$($entry.Group).$($entry.Key)"]
    }

    if (-not $existing) {
        Set-JsonPath $serverConfig 'WorldConfig.WorldConfiguration' ([pscustomobject]@{})
        foreach ($entry in $contract | Where-Object { $_.Group -ne 'Server' }) {
            $value = $values["$($entry.Group).$($entry.Key)"]
            if ($entry.Group -eq 'Creation' -and $entry.Key -eq 'Seed' -and [string]::IsNullOrEmpty([string]$value)) { $value = $null }
            Set-JsonPath $serverConfig ([string]$entry.CreationPath) $value
        }
    }
    else {
        $state = Read-ManagedState $statePath
        $startupProperty = $serverConfig.PSObject.Properties['StartupCommands']
        $startupText = if ($null -eq $startupProperty -or $null -eq $startupProperty.Value) { '' } else { [string]$startupProperty.Value }
        $lines = @($startupText -split "`r?`n" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
        if ($state.Valid) {
            $lines = @($lines | Where-Object { $line = $_; -not @($state.Commands | Where-Object { $_ -ceq $line }).Count })
        }
        elseif ($state.Reason -eq 'invalid') { Write-Warning '[AMP World] state file invalid; preserving all existing startup commands' }

        if ($managed.ApplyToExistingWorld) {
            foreach ($entry in $contract | Where-Object { $_.Lifecycle -in @('restart','unexplored','server') }) {
                $value = ConvertTo-CommandValue $values["$($entry.Group).$($entry.Key)"]
                if ($entry.Lifecycle -eq 'server') { $managedCommands += "/serverconfig $($entry.Command) $value" }
                else { $managedCommands += "/worldconfig $($entry.Command) $value" }
            }
        }
        $combined = @($lines) + @($managedCommands)
        if ($null -eq $startupProperty) { $serverConfig | Add-Member -NotePropertyName StartupCommands -NotePropertyValue ($combined -join "`n") }
        else { $startupProperty.Value = ($combined -join "`n") }
        $stateOutput = [ordered]@{ SchemaVersion=1; ManagedCommands=@($managedCommands) }
    }

    $serverText = ConvertTo-StableJson $serverConfig
    $currentText = [IO.File]::ReadAllText($serverConfigPath)
    $serverChanged = $currentText -cne $serverText
    $serverTemp = if ($serverChanged) { Write-ValidatedTemp $serverConfigPath $serverText } else { $null }
    $stateTemp = $null
    $stateChanged = $false
    if ($existing) {
        $stateText = ConvertTo-StableJson $stateOutput
        $stateChanged = -not (Test-Path -LiteralPath $statePath) -or ([IO.File]::ReadAllText($statePath) -cne $stateText)
        if ($stateChanged) { $stateTemp = Write-ValidatedTemp $statePath $stateText }
    }

    try {
        if ($serverChanged) { Replace-File $serverTemp $serverConfigPath $backupPath; $serverTemp = $null }
        if ($stateChanged) { Replace-File $stateTemp $statePath; $stateTemp = $null }
    }
    catch {
        if ($serverChanged -and (Test-Path -LiteralPath $backupPath -PathType Leaf)) {
            $rollback = Join-Path $dataPath ('.serverconfig.rollback-' + [guid]::NewGuid().ToString('N'))
            [IO.File]::Copy($backupPath, $rollback, $true)
            Replace-File $rollback $serverConfigPath
        }
        throw
    }
    finally {
        if ($serverTemp) { Remove-Item -LiteralPath $serverTemp -Force -ErrorAction SilentlyContinue }
        if ($stateTemp) { Remove-Item -LiteralPath $stateTemp -Force -ErrorAction SilentlyContinue }
    }

    $mode = if ($existing) { 'existing' } else { 'new' }
    $enforcement = $managed.ApplyToExistingWorld.ToString().ToLowerInvariant()
    Write-Output "[AMP World] save=$mode enforcement=$enforcement creation-values=$(if ($existing) { 0 } else { 68 }) managed-commands=$($managedCommands.Count)"
    if ($existing -and $managed.ApplyToExistingWorld -and @($contract | Where-Object Lifecycle -eq 'unexplored').Count -gt 0) {
        Write-Warning '[AMP World] world-generation overrides affect only unexplored chunks and may create visible terrain borders'
    }
}
catch {
    [Console]::Error.WriteLine("[AMP World] ERROR: $($_.Exception.Message)")
    exit 1
}
